local _, ns = ...

-- facdesc: English -> Danish. Entries already in ns.Exact (hand-made) are kept.
local names = {
    ["A hastily-organized group of Druids, working with both the Alliance and the Horde to stop the Nightmare Incursions."] = "En hastigt sammensat gruppe af druiderne, der arbejder sammen med både Alliancen og Horden for at stoppe Mareindfaldene.",
    ["A monastic order of holy warriors sworn to the service of the king of Lordaeron."] = "En klosterorden af hellige krigere, som har svoret at tjene kongen af Herrelande.",
    ["A primarily human criminal organization that operates mostly out of the Alterac Mountains and Hillsbrad Foothills."] = "En overvejende menneskelig kriminel organisation, der for det meste opererer fra Alterac-bjergene og Hillsbrad-forbjergene.",
    ["A remnant of the once powerful elves living in Dire Maul, yet still wise and knowledgeable about great secrets."] = "En rest af de engang mægtige alfer, der bor i Frygtindgydende Stødhammer, men som stadig er kloge og velbevandrede i store hemmeligheder.",
    ["A strong arm of the Steamwheedle Cartel, this port is home to seafaring sailors and back-alley dealers spanning the eastern sea trading routes."] = "En stærk arm af Dampsnedig-kartellet, denne havn er hjemsted for søfarende sømænd og baggadehandlere, der spænder over de østlige havhandelsruter.",
    ["A traveling fair that showcases the weird and the extraordinary.  Often spotted in Elwynn Forest and Mulgore."] = "En rejsende marked, der viser det mærkelige og det usædvanlige.  Ses ofte i Elwynnskoven og Mulgorr.",
    ["An elite cadre of the most powerful wizards in the world and the ruling conclave of magi that leads the magical nation of Dalaran."] = "En elitær kerne af verdens mægtigste troldmænd og det regerende konklave af magikere, der leder den magiske nation Dalarn.",
    ["An order of powerful jailers and marshals of night elf society. They stand vigilant to ensure that no threat can ever escape their extensive underground network of prisons."] = "En orden af mægtige fangevogtere og marskaller i nattenisse-samfundet. De står på vagt for at sikre, at ingen trussel nogensinde kan slippe ud af deres omfattende underjordiske net af fængsler.",
    ["An organization focused on protecting Azeroth from the threat of the Scourge.  Strongholds of the Argent Dawn can be found in the Eastern and Western Plaguelands."] = "En organisation, der fokuserer på at beskytte Azerot mod truslen fra Svøben.  Sølvdæmringens fæstninger findes i de Østlige og Vestlige Pestlande.",
    ["As one of the last uncorrupted furbolg tribes, the Timbermaw seek to preserve their spiritual ways and end the suffering of their brethren."] = "Som en af de sidste ukorrumperede pelsbolg-stammer søger Tømmerkæbe at bevare deres åndelige måder og ende deres brødres lidelse.",
    ["Cairne Bloodhoof leads his people, the Proud Tauren, from this mighty Horde capital."] = "Kærne Blodhov leder sit folk, de Stolte Taurer, fra denne mægtige hovedstad i Horden.",
    ["Capital of the Steamwheedle Cartel and home to goblinhood's finest engineers, alchemists and merchants."] = "Hovedstad for Dampsnedig-kartellet og hjemsted for kobolddommens fineste ingeniører, alkymister og købmænd.",
    ["Charged with the protection and preservation of Mount Hyjal, this splinter faction of the Cenarion Circle welcomes any who are willing to push back the forces of evil."] = "Betroet med at beskytte og bevare Hyjal-bjerget, byder denne udbryderfraktion af Cenarion-kredsen velkommen til alle, der er villige til at drive ondskabens styrker tilbage.",
    ["Elite members of night elf society."] = "Elitemedlemmer af nattenisse-samfundet.",
    ["Exiled for betraying their false prophets, these former members of the Twilight's Hammer seek to forge their own path."] = "Forvist for at have forrådt deres falske profeter søger disse tidligere medlemmer af Tusmørkets Hammer at smede deres egen vej.",
    ["Fierce orcs of the Warsong Clan, locked in battle against the Silverwing Sentinels in Warsong Gulch."] = "Heftige orker fra Krigssang-klanen, låst i slag mod Sølvvinge-vagterne i Krigssang-Gulch.",
    ["Founded by Thrall, this Horde capital city is home to many of the proud orc clans of Durotar."] = "Grundlagt af Trael er denne Horde-hovedstad hjemsted for mange af de stolte orkklaner i Durdotar.",
    ["Led by Sylvanas Windrunner, the Forsaken have joined a tenuous alliance with the Horde and established this capital in the vast depths under the Ruins of Lordaeron."] = "Ledet af Silvanas Vindløber har De Forladte indgået en usikker alliance med Horden og etableret denne hovedstad i de enorme dybder under Ruinerne af Herrelande.",
    ["Loyal partisans for their city, the Theramore Expeditionary Force battles the Darkspear Raiders for control of the so-called Darkspear Islands."] = "Trofaste tilhængere af deres by, Theramore-ekspeditionsstyrken kæmper mod Mørkspyd-plyndrerne om kontrollen over de såkaldte Mørkspyd-øerne.",
    ["Loyal to the troll nation, the Darkspear Raiders battle the Theramore Expeditionary Force for control of their ancestral Darkspear Islands."] = "Tro mod trold-nationen kæmper Mørkspyd-plyndrerne mod Theramore-ekspeditionsstyrken om kontrollen over deres forfædres Mørkspyd-øer.",
    ["One of the last bastions of human power, this Alliance capital is ruled by the child king, Anduin Wrynn."] = "En af de sidste bastioner for menneskelig magt, denne Alliance-hovedstad styres af barnekongen Anduin Rynn.",
    ["Originally commissioned to facilitate trade across the Eastern Kingdoms, the ACA now maintains supply routes to Alliance forces worldwide."] = "Oprindeligt hvervet til at lette handelen på tværs af Østkongerigerne, vedligeholder AHM nu forsyningsruter til Alliance-styrker verden over.",
    ["Outcast members of Stormwind's cavalry, these former riders started anew in the unexplored lands along the eastern coast, establishing their home, new relationships, and trade routes."] = "Udstødte medlemmer af Stormvinds kavaleri, disse tidligere ryttere begyndte på ny i de uudforskede lande langs østkysten og etablerede deres hjem, nye relationer og handelsruter.",
    ["Part of the Steamwheedle Cartel, this goblin city provides a neutral haven for those that wish to trade goods and services in the Barrens."] = "En del af Dampsnedig-kartellet, denne kobold-by er et neutralt fristed for dem, der ønsker at handle med varer og tjenester i Ødemarken.",
    ["Staunch defenders of Ashenvale, locked in battle against the Warsong Outriders in Warsong Gulch."] = "Trofaste forsvarere af Askedalen, låst i slag mod Krigssang-forposterne i Krigssang-Gulch.",
    ["The Alliance capital is populated by Night Elves and is located in the island of Teldrassil.  Ruled by the Priestess of the Moon, Tyrande Whisperwind."] = "Alliancens hovedstad er befolket af Nattealferne og ligger på øen Teldrasil.  Hersket over af Månens Præstinde, Tyrande Hviskevind.",
    ["The Barkskin are among the few furbolg tribes untouched by corruption, and dedicate themselves to safeguarding their spiritual heritage to bring harmony back to Hyjal."] = "Barkhud er blandt de få pelsbolg-stammer, som korruptionen ikke har nået, og de vier sig til at værne om deres åndelige arv for at bringe harmoni tilbage til Hyjal-området.",
    ["The Cenarion Scouts are young nature enthusiasts dedicated to exploring and protecting the wilds of Azeroth."] = "Cenarion-spejderne er unge naturentusiaster, som vier sig til at udforske og beskytte Azerots vildmark.",
    ["The Defilers seek to claim Arathi Basin's valuable resources for the Horde."] = "Skænderne forsøger at gøre sig til herrer over Arathi-bækkenets værdifulde ressourcer for Horden.",
    ["The Earthen Ring is a loose collective of Horde-aligned shamans and druids who seek to maintain and nurture the balance of nature on Azeroth."] = "Jordringen er en løs sammenslutning af Horden-allierede shamaner og druider, som søger at opretholde og pleje naturens balance på Azerot.",
    ["The Frostwolf Clan seeks to drive out the dwarves of the Stormpike Expedition from Alterac Valley."] = "Frostulv-klanen søger at jage dværgene fra Stormspids-ekspeditionen ud af Alterac-dalen.",
    ["The High Order are the Skyborne descendants of the Highborne magisters of Eldre'Thalas. Having spent the past 10,000 years in the realm of Skywall, members of the High Order seek to reclaim the ancient arcane knowledge of their forebears."] = "Den Høje Orden er de himmelbårne efterkommere af Eldre'Thalas' højfødte magistre. Efter at have tilbragt de seneste 10.000 år i Himmelmurens rige, søger medlemmerne af Den Høje Orden at genvinde deres forfædres gamle arkane viden.",
    ["The Horde's robust supply network fuels its rapid expansion across Kalimdor and beyond."] = "Hordens robuste forsyningsnetværk driver dens hurtige ekspansion over Kalimdør og videre.",
    ["The League of Arathor seeks to reclaim lost land of Arathi Basin for their benefactors in Stormwind."] = "Arator-ligaen søger at genvinde det tabte land i Arathi-bækkenet for deres velyndere i Stormvind.",
    ["The Stormpike Dwarves have set up residence in Alterac Valley, where they're locked in battle with the Frostwolf Orcs."] = "Stormspids-dværgene har slået sig ned i Alterac-dalen, hvor de er låst i kamp med Frostulv-orkerne.",
    ["The Windshapers are shamanistic spiritual leaders of the Skyborne people on Zephras Isle. They honor the elements and seek to gain a better understanding of the nature of the elemental plane to protect the shen'dorei way of life within Skywall."] = "Vindformerne er de shamanistiske åndelige ledere for det himmelbårne folk på Vindras-øen. De ærer elementerne og søger at opnå en bedre forståelse af elementarplanets natur for at beskytte Stjernebørnenes levevis inden for Himmelmuren.",
    ["The descendants of the Bronze Dragonflight are the guardians of time and care little for the mortal races."] = "Efterkommerne af Den Bronze Drageflugt er tidens vogtere og bekymrer sig ikke meget om de dødelige racer.",
    ["The druids of Cenarion Circle are guardians of nature and make their home in tranquil Moonglade."] = "Druiderne i Cenarion-kredsen er naturens vogtere og har deres hjem i det stille Månelunden.",
    ["The dwarves of the Thorium Brotherhood epitomize excellence in craftsmanship and are bent on unlocking the secrets of Blackrock Mountain."] = "Dværgene i Thorium-broderskabet er det ypperste eksempel på håndværkskunst og er besatte af at låse hemmelighederne op i Sortklippebjerget.",
    ["The former denizens of Gnomeregan, now living in exile in Ironforge and in league with the Alliance."] = "De tidligere indbyggere i Gnomregan, som nu lever i eksil i Jernsmede og er i forbund med Alliancen.",
    ["The ravasaurs of Un'Goro Crater are incredibly deadly, but a few individuals have learned how to tame them."] = "Ravasaurerne i Un'Goro-krateret er utroligt dødbringende, men et par enkeltpersoner har lært at tæmme dem.",
    ["The secretive druids of the Shadowgale Forest. They operate independently, apart from any other faction on Zephras Isle."] = "De hemmelighedsfulde druider i Skyggestormsskoven. De opererer uafhængigt af enhver anden fraktion på Vindras-øen.",
    ["The skies are red, and your senses are overpowered with the thirst for blood!"] = "Himlene er røde, og dine sanser er overmandet af tørsten efter blod!",
    ["These bloodthirsty corsairs are the bane of many a merchant in the high seas.  Sworn enemies of Booty Bay."] = "Disse blodtørstige kaprere er en plage for mange købmænd på det åbne hav.  Svorne fjender af Bytteviken.",
    ["These centaur have made their home in the eastern region of Desolace.  Mortal enemies of the Gelkis Centaur."] = "Disse kentaurer har gjort sig hjemme i den østlige region af Forødelse.  Dødelige fjender af Gellekis-kentaurerne.",
    ["These centaur have made their home in the southern region of Desolace.  Mortal enemies of the Magram Centaur."] = "Disse kentaurer har gjort sig hjemme i den sydlige region af Forødelse.  Dødelige fjender af Magrom-kentaurerne.",
    ["These elementals have made their home on the islands east of Azshara.  Sworn enemies of the armies of Ragnaros."] = "Disse elementarer har gjort sig hjemme på øerne øst for Azsyra.  Svorne fjender af Ragnarøs' hære.",
    ["These trolls have come to Yojamba Isle in an effort to recruit help against the resurrected Blood God and his Atal'ai Priests in Zul'Gurub."] = "Disse trolde er kommet til Yojamba-øen for at hverve hjælp mod den genoplivede Blodgud og hans Atal'aj-præster i Zul'Gurb.",
    ["This Alliance capital is the pride of the Dun Morogh dwarves.  Home to King Magni."] = "Denne Alliance-hovedstad er Dun Frostbakkes dværges stolthed.  Hjem for Kong Magni.",
    ["This booming coastal city is run by Baron Revilgaz of the Blackwater Raiders.  Mortal enemies of the Bloodsail Buccaneers and part of the Steamwheedle Cartel."] = "Denne blomstrende kystby styres af Baron Tyranbrand fra Sortvands-razziaerne.  Dødelige fjender af Blodsejl-fribytterne og en del af Dampsnedig-kartellet.",
    ["This faction only exists to test the editing of faction names and descriptions..."] = "Denne fraktion eksisterer kun for at teste redigeringen af fraktionsnavne og -beskrivelser...",
    ["This guild of thieves and assassins welcomes only those of extraordinary prowess into its fold.  Sworn rivals of the Syndicate."] = "Dette gilde af tyve og snigmordere optager kun dem med ekstraordinær duelighed i sine rækker.  Svorne rivaler af Syndikatet.",
    ["This small group of reclusive night elves raises and trains wintersabers in the Winterspring area."] = "Denne lille gruppe af tilbagetrukne nattealfer opdrætter og træner vintersabler i Vinterkilde-området.",
    ["This trading post is run by the goblins of the Steamwheedle Cartel and it sits in the crossroads of Winterspring's main trade routes."] = "Denne handelspost drives af kobolderne fra Dampsnedig-kartellet, og den ligger i krydsningspunktet for Vinterkildes vigtigste handelsruter.",
    ["This tribe of exiled trolls has joined forces with Thrall and the Horde.  They now call Durotar their home, which they share with their orc allies."] = "Denne stamme af forviste trolde har sluttet sig sammen med Trael og Horden.  De kalder nu Durdotar deres hjem, som de deler med deres ork-allierede.",
    ["Though not a part of the Alliance, the dwarves of Aerie Peak have opened their doors to it and hold the Horde as enemies."] = "Selvom de ikke er en del af Alliancen, har dværgene fra Ørnerede-toppen åbnet deres døre for den og ser på Horden som fjender.",
    ["Used for Naxxramas NPCs"] = "Brugt til Naxxrammas-NPC'er",
    ["Will it break? Let's find out!"] = "Vil den gå i stykker? Lad os finde ud af det!",
}
for en, da in pairs(names) do
    if ns.Exact[en] == nil then ns.Exact[en] = da end
end
